(() => {
  if (typeof window === 'undefined') return
  if (window.Tesseract) return

  window.Tesseract = {
    __pdfStudioCapability: 'compatibility-stub-no-ocr',
    __pdfStudioReason: 'A production Tesseract worker, WASM core, and trained-language data are not bundled in this release.',
    async createWorker() {
      throw new Error('Production OCR engine assets are not installed in this release.')
    }
  }
})()
